+  return {
+    ok: true,
+    issuer,
+    resource,
+    files: ["app/.dev.vars", "mcp/.dev.vars", ".data/local-oauth.json"],
+    next: ["pnpm dev:app:auth", "pnpm dev:mcp", "pnpm test:local:oauth"],
+  };
+}
+
+if (fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
